using FamilyVeda.Application.Common;
using FamilyVeda.Domain.Common;
using FamilyVeda.Domain.Identity;
using FamilyVeda.Infrastructure.Persistence;
using FamilyVeda.Infrastructure.Records;
using FluentAssertions;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Options;

namespace FamilyVeda.UnitTests;

public sealed class LabReportDurableStorageTests
{
    [Fact]
    public async Task Upload_StoresImageBytesInDatabase_NotOnContainerFilesystem()
    {
        var (db, service, member, storageRoot) = await CreateAsync();
        var png = SyntheticPng(64, 32);

        var result = await service.UploadLabReportAsync(member.Id, "synthetic-lab.png", "image/png", png.Length, new MemoryStream(png), null, CancellationToken.None);

        var stored = await db.LabReportFiles.SingleAsync(x => x.LabReportId == result.Id);
        stored.Content.Should().Equal(png);
        (await db.LabReports.SingleAsync(x => x.Id == result.Id)).StoredFileName.Should().StartWith("db:");
        Directory.Exists(storageRoot).Should().BeFalse();
    }

    [Fact]
    public async Task Upload_WhenStreamLongerThanDeclaredSize_RejectsAndStoresNothing()
    {
        var (db, service, member, _) = await CreateAsync();
        var png = SyntheticPng(64, 32);

        var upload = () => service.UploadLabReportAsync(member.Id, "synthetic-lab.png", "image/png", png.Length - 1, new MemoryStream(png), null, CancellationToken.None);

        await upload.Should().ThrowAsync<ValidationException>();
        (await db.LabReports.CountAsync()).Should().Be(0);
        (await db.LabReportFiles.CountAsync()).Should().Be(0);
    }

    private static async Task<(AppDbContext Db, RecordService Service, Member Member, string StorageRoot)> CreateAsync()
    {
        var db = new AppDbContext(new DbContextOptionsBuilder<AppDbContext>().UseInMemoryDatabase(Guid.NewGuid().ToString()).Options);
        var user = new UserAccount { Email = "synthetic-durable@example.invalid", PasswordHash = "synthetic", DisplayName = "Synthetic User", UserType = UserType.FamilyUser };
        var family = new Family { Name = "Synthetic Durable Family", CreatedByUser = user };
        var member = new Member { Family = family, User = user, DisplayName = "Synthetic Member", DateOfBirth = new DateOnly(1990, 1, 1), Role = FamilyRole.Head };
        db.AddRange(user, family, member);
        await db.SaveChangesAsync();
        var storageRoot = Path.Combine(Path.GetTempPath(), $"fv-durable-{Guid.NewGuid():N}");
        var service = new RecordService(db, new StubCurrentUser(user.Id), Options.Create(new StorageOptions { LabReportPath = storageRoot }));
        return (db, service, member, storageRoot);
    }

    private static byte[] SyntheticPng(int width, int height)
    {
        var bytes = new byte[64];
        new byte[] { 0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A }.CopyTo(bytes, 0);
        System.Buffers.Binary.BinaryPrimitives.WriteInt32BigEndian(bytes.AsSpan(16, 4), width);
        System.Buffers.Binary.BinaryPrimitives.WriteInt32BigEndian(bytes.AsSpan(20, 4), height);
        return bytes;
    }

    private sealed class StubCurrentUser(Guid userId) : ICurrentUser
    {
        public Guid UserId => userId;
        public bool IsAuthenticated => true;
        public UserType UserType => UserType.FamilyUser;
    }
}
